mapper.select:
SELECT no, title, first_image1 AS image, addr1, addr2, tel, latitude, longitude, content_type_id, homepage, overview, al.id, likes, COUNT(*) OVER() AS totalCount FROM attractions a LEFT JOIN attraction_likes al ON a.no = al.attraction_id WHERE latitude BETWEEN #{mapBound.southWest.latitude} AND #{mapBound.northEast.latitude} AND longitude BETWEEN #{mapBound.southWest.longitude} AND #{mapBound.northEast.longitude}
AND content_type_id = #{contentType}
AND title LIKE #{likeKeyword}
ORDER BY no LIMIT ${pageable.offset}, ${pageable.pageSize}

mapper.update:
UPDATE attractions
SET likes = likes + 1
WHERE no = #{attractionId}

UPDATE attractions
SET likes = CASE WHEN likes > 0 THEN likes - 1 ELSE 0 END
WHERE no = #{attractionId}

UPDATE plan
SET likes = likes + 1
WHERE plan_id = #{planId}

UPDATE plan
SET likes = CASE WHEN likes > 0 THEN likes - 1 ELSE 0 END
WHERE plan_id = #{planId}

mapper.select:
SELECT record_id, title, content, plan_id
FROM record
WHERE plan_id = #{planId}

SELECT image_url
FROM record_image
WHERE record_id = #{recordId}
